#!/usr/bin/env bash
# Usage: bash prove.sh input.json
# Generates a witness for {"age": "...", "threshold": "..."}; exits non-zero
# if the inputs do not satisfy the circuit. All rules are enforced in-circuit;
# this script only translates JSON into a Prover TOML file.
set -euo pipefail

if [[ $# -ne 1 ]]; then
  echo "usage: $0 input.json" >&2
  exit 2
fi

input="$(cd "$(dirname "$1")" && pwd)/$(basename "$1")"
cd "$(dirname "${BASH_SOURCE[0]}")"

prover_name="Prover_$$"
trap 'rm -f "${prover_name}.toml"' EXIT

# JSON string literals are valid TOML basic strings, so values are quoted safely.
node -e '
const fs = require("fs");
const input = JSON.parse(fs.readFileSync(process.argv[1], "utf8"));
const lines = ["age", "threshold"].map((k) => {
  if (!(k in input)) throw new Error(`missing input: ${k}`);
  return `${k} = ${JSON.stringify(String(input[k]))}`;
});
fs.writeFileSync(process.argv[2], lines.join("\n") + "\n");
' "$input" "${prover_name}.toml"

nargo execute --prover-name "$prover_name" "witness_$$" >/dev/null
rm -f "target/witness_$$.gz"

/// Proves that a private `age` is a byte-sized integer that is at least the
/// public byte-sized `threshold`.
///
/// Inputs are taken as `Field`s and range-checked in-circuit, so that the
/// constraints themselves (not ABI decoding) reject out-of-range values such as
/// 256 or arbitrary large field elements.
fn main(age: Field, threshold: pub Field) {
    let age = to_u8(age);
    let threshold = to_u8(threshold);
    assert(age >= threshold, "age is below threshold");
}

/// Constrains `x` to fit in 8 bits and returns it as a `u8`.
fn to_u8(x: Field) -> u8 {
    x.assert_max_bit_size::<8>();
    x as u8
}

#[test]
fn accepts_above_threshold() {
    main(25, 18);
}

#[test]
fn accepts_equal_to_threshold() {
    main(18, 18);
}

#[test]
fn accepts_bounds() {
    main(0, 0);
    main(255, 0);
    main(255, 255);
}

#[test(should_fail_with = "age is below threshold")]
fn rejects_below_threshold() {
    main(17, 18);
}

#[test(should_fail)]
fn rejects_age_out_of_range() {
    main(256, 18);
}

#[test(should_fail)]
fn rejects_threshold_out_of_range() {
    main(255, 256);
}

#[test(should_fail)]
fn rejects_huge_field_element() {
    // p - 1, i.e. "-1" in the field.
    main(-1, 0);
}

#[test(should_fail)]
fn rejects_wrapped_age() {
    // 256 + 20 would truncate to 20 >= 18 without the range check.
    main(276, 18);
}
